using System;
using System.Collections;
using System.IO;
using System.Text;
using UnityEngine;
// Isolated, position-controlled lifecycle checks. Does not use a user's campaign file.
public sealed class PassengerBehaviorProbe:MonoBehaviour {
 DriveSession s;int checks,serial;readonly StringBuilder report=new StringBuilder();bool reload;
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void Attach(){var a=Environment.GetCommandLineArgs();if(Array.IndexOf(a,"-passengerBehaviorTest")>=0||Array.IndexOf(a,"-passengerBehaviorReloadTest")>=0)new GameObject("Passenger behavior probe").AddComponent<PassengerBehaviorProbe>();}
 void Check(bool ok,string why){checks++;report.AppendLine((ok?"PASS ":"FAIL ")+why);if(!ok)throw new Exception(why);}
 void Stop(int i){var p=s.jobs.stops[i];s.taxi.body.position=p.Kerb+Vector3.up*.65f;s.taxi.body.rotation=Quaternion.LookRotation(p.Direction);s.taxi.transform.SetPositionAndRotation(s.taxi.body.position,s.taxi.body.rotation);Physics.SyncTransforms();s.requests.AdvanceSafeStop(2.1f);}
 void FreezeSystems(){s.business.enabled=false;s.jobs.enabled=false;s.jobs.nav.enabled=false;s.requests.enabled=false;s.law.enabled=false;s.manners.enabled=false;s.GetComponent<ServiceLawZones>().enabled=false;s.taxi.enabled=false;s.taxi.body.isKinematic=true;s.taxi.body.interpolation=RigidbodyInterpolation.None;foreach(var c in s.traffic.cars){c.Recycle();c.enabled=false;}}
 void Fresh(){s.business.settings=PrototypeSettings.ForThreeDays();s.business.ledger=new EconomyLedger(s.business.settings);s.business.passengers.Clear();s.business.enabledCampaign=s.business.useV2=true;s.business.preparing=false;s.paused=false;Time.timeScale=1;s.law.ids=new PrototypeIds("behavior-probe-"+(serial++));s.law.ledger=new LawLedger();s.law.tripId="";s.jobs.ClearForDay();s.jobs.ForcedRideCase=DrunkRideCase.Random;s.GetComponent<RideCompletionPanel>().Close();}
 void Begin(PassengerType type){s.jobs.ForcedPassengerType=type;string seed="probe-"+serial+"-"+type;var offer=new JobOffer{pickup=0,drop=3,fare=5000,seconds=300,requiredScore=70,distance=s.jobs.nav.Distance(s.jobs.stops[0],s.jobs.stops[3]),candidateSeed=seed};s.jobs.offers[0]=offer;Stop(0);Check(s.jobs.Accept(0)&&s.jobs.Interact(),"begin "+type);s.requests.AdvanceSafeStop(2.1f);Check(s.jobs.Behavior!=null&&s.jobs.Behavior.Type==type,"actual type "+type);}
 // Synchronous position fixtures model a later input frame explicitly; the coroutine below also tests real frame boundaries.
 void NextInputFrame(){typeof(PassengerRequestUI).GetField("responseBlockedFrame",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).SetValue(s.requests,Time.frameCount-1);}
 void Answer(int choice){NextInputFrame();if(s.requests.HasPendingChoice)s.requests.Choose(PassengerReply.Defer);NextInputFrame();s.requests.AdvanceSafeStop(2.1f);Check(s.jobs.RespondBehavior(choice),"answer "+s.jobs.Behavior.Type+"/"+choice);}
 PassengerJobsSnapshot RoundTrip(){var state=JsonUtility.FromJson<PassengerJobsSnapshot>(JsonUtility.ToJson(s.jobs.CaptureLive()));s.jobs.RestoreLive(state);s.requests.AdvanceSafeStop(2.1f);return state;}
 void Deliver(){Stop(s.jobs.current.drop);Check(s.jobs.Interact(),"first valid arrival");if(s.jobs.Active&&s.jobs.Behavior.WorkRemaining>0)s.jobs.AdvanceBehavior(10);if(s.jobs.Active&&s.jobs.DrunkRide.Waiting){s.jobs.DrunkRide.Advance(30,1);Check(s.jobs.Interact(),"wake after safe wait");}Check(!s.jobs.Active&&s.business.passengers.Count==1,"one completed passenger result");Check(s.business.passengers[0].request.Contains(s.jobs.Behavior.TypeLabel),"type and variant in detailed result");}
 void CompositionChecks(){
  Check(s.business.SavePath.Contains("artifacts"),"composition fixture uses isolated campaign save");
  string profile=ContentTuning.CaptureJson();try{
   var payload=ContentJson.Object(ContentJson.Parse(profile));bool found=false;
   foreach(object item in ContentJson.Array(payload["values"])){var row=ContentJson.Object(item);if((string)row["id"]=="passenger.presets"){row["value"]="{\"version\":1,\"presets\":[{\"id\":\"drunk-quiet-luggage\",\"name\":\"조용한 귀가와 짐\",\"enabled\":true,\"weight\":1,\"pool\":\"Drunk\",\"traits\":[\"body.drunk\",\"speech.quiet\",\"item.luggage\"],\"intro\":\"집까지 부탁해요\"}]}";found=true;}}
   Check(found,"runtime catalog exposes preset key");payload["contentHash"]=ContentTuning.ComputeHash(payload);ContentTuning.UseJson(ContentJson.Stringify(payload));
   Fresh();s.jobs.ForcedPassengerType=null;
   var care=s.business.ledger.Care.Snapshot();care.encounterReserved=true;care.encounterType=PassengerType.Drunk;care.encounterSelectionSeed="composition-fixed";typeof(EconomyLedger).GetProperty("Care").SetValue(s.business.ledger,VehicleCare.Restore(care),null);
   s.jobs.offers[0]=new JobOffer{pickup=0,drop=3,fare=5000,seconds=300,requiredScore=70,distance=s.jobs.nav.Distance(s.jobs.stops[0],s.jobs.stops[3]),candidateSeed="composition-fixed"};Stop(0);
   Check(s.jobs.Accept(0)&&s.jobs.Interact(),"configured passenger selected through actual boarding path");
   Check(s.jobs.Behavior.PresetId=="drunk-quiet-luggage"&&s.jobs.Behavior.Type==PassengerType.Luggage&&s.jobs.Behavior.Pool==PassengerType.Drunk,"preset identity pool and action remain independent");
   Check(s.jobs.trip.State==TripState.ToPickup&&!s.jobs.Behavior.Boarded,"composed luggage blocks boarding until prepared");Answer(0);s.jobs.AdvanceBehavior(4);RoundTrip();
   Check(s.jobs.Behavior.PreparationRemaining==6&&s.jobs.Behavior.Quiet,"JSON live restore preserves partial work and explicit quiet");s.jobs.AdvanceBehavior(6);
   Check(s.jobs.trip.State==TripState.OnTrip&&s.jobs.DrunkRide.IsDrunk,"luggage boarding starts actual drunk state");Check(s.business.ledger.Care.Snapshot().encounterDrunks==1,"drunk cap consumes pool rather than luggage module");
   RoundTrip();Check(s.jobs.DrunkRide.IsDrunk&&s.jobs.Behavior.PresetId=="drunk-quiet-luggage"&&s.jobs.Behavior.Quiet,"composed onboard state survives real restore");
   s.jobs.DrunkRide.SleepPlanned=false;s.jobs.DrunkRide.VomitPlanned=true;s.jobs.nav.remaining=0;
   var updateCare=typeof(PassengerJobs).GetMethod("UpdateCare",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic);updateCare.Invoke(s.jobs,null);
   Check(s.jobs.DrunkRide.Warned&&!string.IsNullOrEmpty(s.jobs.VisibleCareDialogue),"explicit quiet keeps critical vomit warning visible");s.jobs.DrunkRide.Elapsed+=3.1f;updateCare.Invoke(s.jobs,null);
   Check(s.jobs.DrunkRide.Vomited&&s.business.ledger.Care.NeedsWash&&s.business.ledger.Care.AcceptanceLocked,"actual care update locks new boarding immediately on vomit");int cleanBeforeExit=s.jobs.Cleanliness;RoundTrip();updateCare.Invoke(s.jobs,null);Check(s.jobs.Cleanliness==cleanBeforeExit&&s.business.ledger.Care.NeedsWash,"vomit restore preserves lock without applying exit dirt early");
   Stop(s.jobs.current.drop);Check(s.jobs.Interact()&&s.jobs.Active&&s.jobs.Behavior.UnloadRemaining>0,"arrival still requires unloading");RoundTrip();s.jobs.AdvanceBehavior(10);Check(!s.jobs.Active&&s.business.passengers.Count==1,"unload settles composed passenger once");
   Check(s.business.ledger.Care.Snapshot().encounterDrunks==1,"restore and settlement never double count drunk");
   Check(s.jobs.Cleanliness<=10&&!s.business.ledger.Care.Finish(s.law.tripId,true),"vomit exit caps cleanliness and rejects duplicate settlement");int finalClean=s.jobs.Cleanliness;RoundTrip();s.jobs.ApplyBehaviorDirt();Check(s.jobs.Cleanliness==finalClean,"settled composition restore cannot apply dirt twice");
   CompositionRepresentativeChecks(PassengerType.Comfort,PassengerType.Food,RequestKind.Comfort,new[]{"body.sensitive","item.food"});
   CompositionRepresentativeChecks(PassengerType.Errand,PassengerType.MuddyLuggage,RequestKind.ViaStop,new[]{"purpose.errand","item.muddy"});
  }finally{ContentTuning.UseJson(profile);}
 }
 void CompositionRepresentativeChecks(PassengerType pool,PassengerType action,RequestKind request,string[] traits){
  var profile=ContentJson.Object(ContentJson.Parse(ContentTuning.CaptureJson()));var preset=new System.Collections.Generic.Dictionary<string,object>{{"id","composed-"+pool.ToString().ToLowerInvariant()},{"name","요청과 소지품"},{"enabled",true},{"weight",1},{"pool",pool.ToString()},{"traits",traits},{"intro","함께 부탁해요"}};string json=ContentJson.Stringify(new System.Collections.Generic.Dictionary<string,object>{{"version",1},{"presets",new[]{preset}}});foreach(object item in ContentJson.Array(profile["values"])){var row=ContentJson.Object(item);if((string)row["id"]=="passenger.presets")row["value"]=json;}profile["contentHash"]=ContentTuning.ComputeHash(profile);ContentTuning.UseJson(ContentJson.Stringify(profile));
  Fresh();s.jobs.ForcedPassengerType=null;string seed="";for(int i=0;i<100;i++){string candidate="composition-request-"+i;if(PassengerRequestSchedule.Create(candidate,(RequestKind[])Enum.GetValues(typeof(RequestKind))).Capture().slots.Length>0){seed=candidate;break;}}Check(seed.Length>0,"representative fixture has an existing request slot");
  var care=s.business.ledger.Care.Snapshot();care.encounterReserved=true;care.encounterType=pool;care.encounterSelectionSeed=seed;typeof(EconomyLedger).GetProperty("Care").SetValue(s.business.ledger,VehicleCare.Restore(care),null);
  s.jobs.offers[0]=new JobOffer{pickup=0,drop=3,fare=5000,seconds=300,requiredScore=70,distance=s.jobs.nav.Distance(s.jobs.stops[0],s.jobs.stops[3]),candidateSeed=seed};Stop(0);Check(s.jobs.Accept(0)&&s.jobs.Interact(),"composed representative enters actual boarding "+pool);Check(s.jobs.Behavior.Type==action&&s.jobs.Behavior.RepresentativeType==pool,"composed action and representative selected "+pool);
  Answer(1);if(s.jobs.trip.State==TripState.ToPickup)Check(s.jobs.Interact(),"unprotected muddy item boards after response");
  var slots=s.requests.CaptureLive().schedule.slots;Check(slots.Length>0&&slots[0].kind==request,"actual Begin binds representative slot "+request);RoundTrip();Check(s.requests.CaptureLive().schedule.slots[0].kind==request&&s.jobs.Behavior.Type==action,"JSON restore preserves representative and item "+request);
  if(action==PassengerType.Food){s.jobs.Behavior.SpillPlanned=false;s.jobs.Behavior.Advance(25,false,true,.6f,100);s.jobs.ApplyBehaviorDirt();Check(s.jobs.Behavior.ConsumptionOccurred&&s.jobs.Cleanliness==100-ContentTuning.Int("effect.food.crumbs",2),"composed food actually consumes and soils");int clean=s.jobs.Cleanliness;RoundTrip();s.jobs.ApplyBehaviorDirt();Check(s.jobs.Cleanliness==clean,"composed food restore does not soil twice");}
  Deliver();if(action==PassengerType.MuddyLuggage){Check(s.jobs.Behavior.MudOccurred&&s.jobs.Cleanliness==98-ContentTuning.Int("effect.muddy.dirt",5),"composed muddy item soils only on real exit");int clean=s.jobs.Cleanliness;s.jobs.ApplyBehaviorDirt();Check(s.jobs.Cleanliness==clean,"composed muddy exit dirt is replay safe");}
 }
 void BeginOverrideCase(PassengerType pool,string trait,params string[] pairs){
  var rows=new System.Collections.Generic.List<object>();for(int i=0;i<pairs.Length;i+=2)rows.Add(new System.Collections.Generic.Dictionary<string,object>{{"id",pairs[i]},{"value",pairs[i+1]}});
  var preset=new System.Collections.Generic.Dictionary<string,object>{{"id","individual"},{"name","개별 승객"},{"enabled",true},{"weight",1},{"pool",pool.ToString()},{"traits",new[]{trait}},{"intro",""},{"overrides",rows}};
  string json=ContentJson.Stringify(new System.Collections.Generic.Dictionary<string,object>{{"version",2},{"presets",new[]{preset}}});var profile=ContentJson.Object(ContentJson.Parse(ContentTuning.CaptureJson()));foreach(object o in ContentJson.Array(profile["values"])){var row=ContentJson.Object(o);if((string)row["id"]=="passenger.presets")row["value"]=json;}profile["contentHash"]=ContentTuning.ComputeHash(profile);ContentTuning.UseJson(ContentJson.Stringify(profile));
  Fresh();s.jobs.ForcedPassengerType=null;var care=s.business.ledger.Care.Snapshot();care.encounterReserved=true;care.encounterType=pool;care.encounterSelectionSeed="override-fixed";typeof(EconomyLedger).GetProperty("Care").SetValue(s.business.ledger,VehicleCare.Restore(care),null);
  s.jobs.offers[0]=new JobOffer{pickup=0,drop=3,fare=5000,seconds=300,requiredScore=70,distance=s.jobs.nav.Distance(s.jobs.stops[0],s.jobs.stops[3]),candidateSeed="override-fixed"};Stop(0);Check(s.jobs.Accept(0)&&s.jobs.Interact(),"individual preset enters real boarding "+pool);Check(s.jobs.Behavior.PresetOverrides.Length==rows.Count,"individual rows frozen on passenger");
 }
 void OverrideChecks(){
  Check(s.business.SavePath.Contains("artifacts"),"individual fixture uses isolated save");string baseline=ContentTuning.CaptureJson();try{
   foreach(int bonus in new[]{1,7}){
    bool spill=bonus==7;int crumbs=spill?9:2;
    BeginOverrideCase(PassengerType.Food,"item.food","effect.food.spillPercent",spill?"100":"0","effect.food.crumbs",crumbs.ToString(),"effect.food.spill","4","choice.type.Food.1.immediate.satisfaction",bonus.ToString(),"type.Food.choice.1","이 승객의 음식 허락","request.Quiet.reply.Accept","이 승객에게 드리는 답변","request.Quiet.prompt","개별 조용한 운행 요청");
    Check(s.jobs.Behavior.ChoiceLabels[1]=="이 승객의 음식 허락","individual action reply shown");Check(s.jobs.Behavior.SpillPlanned==spill,"individual food0/100 roll fixed before consent");Answer(1);Check(s.jobs.ChoiceEffects.SatisfactionDelta==bonus,"actual immediate effect matches individual "+bonus);RoundTrip();Check(s.jobs.ChoiceEffects.SatisfactionDelta==bonus,"resolved effect validates on JSON restore");
    s.jobs.Behavior.Advance(30,false,true,.6f,100);s.jobs.ApplyBehaviorDirt();int expected=100-crumbs-(spill?4:0);Check(s.jobs.Cleanliness==expected,"individual actual food soil "+expected);RoundTrip();s.jobs.ApplyBehaviorDirt();Check(s.jobs.Cleanliness==expected,"individual food restore no duplicate dirt");
    s.requests.BeginKind(RequestKind.Quiet);NextInputFrame();Check(PassengerRequestObservation.Prompt(RequestKind.Quiet,s.jobs.PassengerContent)=="개별 조용한 운행 요청","individual request prompt resolved");Check(s.requests.Choose(PassengerReply.Accept)&&s.requests.request.SpokenLine("fallback")=="이 승객에게 드리는 답변","actual request response uses explicit individual text");
    Deliver();Check(s.jobs.Cleanliness==expected-2,"ordinary exit dirt stays separate from individual food");
   }
   foreach(int seconds in new[]{3,17}){BeginOverrideCase(PassengerType.Luggage,"item.luggage","effect.luggage.prepareSeconds",seconds.ToString());Answer(0);s.jobs.AdvanceBehavior(seconds-1);Check(s.jobs.trip.State==TripState.ToPickup&&s.jobs.Behavior.PreparationRemaining==1,"individual luggage requires exact seconds "+seconds);RoundTrip();s.jobs.AdvanceBehavior(1);Check(s.jobs.trip.State==TripState.OnTrip,"individual luggage timer survives restore and boards");Deliver();}
   foreach(int percent in new[]{0,100}){BeginOverrideCase(PassengerType.Drunk,"body.drunk","type.Drunk.vomitPercent",percent.ToString(),"type.Drunk.sleepPercent",percent.ToString());Check(s.jobs.DrunkRide.VomitPlanned==(percent==100)&&s.jobs.DrunkRide.SleepPlanned==(percent==100),"actual drunk plan respects individual0/100");RoundTrip();Check(s.jobs.DrunkRide.VomitPlanned==(percent==100),"individual drunk plan frozen across restore");}
  }finally{ContentTuning.UseJson(baseline);}Check(ContentTuning.CaptureJson()==baseline,"individual checks restore shared session profile");
 }
 void RosterChecks(){
  Check(s.business.SavePath.Contains("artifacts"),"roster fixture uses isolated campaign save");string prior=ContentTuning.CaptureJson();try{
   ContentTuningRuntime.LoadActivePath(Path.Combine("artifacts","passenger-roster-v1","absent-"+Guid.NewGuid().ToString("N")+".json"));var roster=PassengerPresetCatalog.Parse(ContentTuning.Text("passenger.presets",""));Check(!ContentTuningRuntime.HasOverride&&roster.Length==24,"missing active profile loads actual packaged24 defaults");int enabled=0;foreach(var p in roster)if(p.enabled&&p.weight>0)enabled++;Check(enabled==23,"packaged roster has23 active passengers");Check(!ContentTuning.Flag("request.ShortRoad.enabled",true)&&!ContentTuning.Flag("request.RouteAdvice.enabled",true),"packaged short and fast route requests disabled");
   int delivered=0;var all=(PassengerType[])Enum.GetValues(typeof(PassengerType));var kinds=(RequestKind[])Enum.GetValues(typeof(RequestKind));
   foreach(var definition in roster){if(definition.overrides.Length==0)continue;Fresh();s.jobs.ForcedPassengerType=null;var pool=(PassengerType)Enum.Parse(typeof(PassengerType),definition.pool);string seed=null;
    for(int i=0;i<2048;i++){string candidate="roster-player-"+i;var selected=PassengerBehaviorState.CreateConfigured(candidate,pool,all,null);if(selected.PresetId==definition.id&&(selected.RepresentativeType==PassengerType.General||PassengerRequestSchedule.Create(candidate,kinds).Capture().slots.Length>0)){seed=candidate;break;}}
    Check(seed!=null,"default weighted draw reaches new passenger "+definition.id);var care=s.business.ledger.Care.Snapshot();care.encounterReserved=true;care.encounterType=pool;care.encounterSelectionSeed=seed;typeof(EconomyLedger).GetProperty("Care").SetValue(s.business.ledger,VehicleCare.Restore(care),null);
    s.jobs.offers[0]=new JobOffer{pickup=0,drop=3,fare=5000,seconds=300,requiredScore=70,distance=s.jobs.nav.Distance(s.jobs.stops[0],s.jobs.stops[3]),candidateSeed=seed};Stop(0);Check(s.jobs.Accept(0)&&s.jobs.Interact(),"new default passenger enters real boarding "+definition.id);Check(s.jobs.Behavior.PresetId==definition.id,"actual map eligibility preserves selected new preset "+definition.id);
    if(s.jobs.DrunkRide!=null)s.jobs.DrunkRide.Advance(7,0);if(s.jobs.Behavior.HasChoice)Answer(s.jobs.Behavior.Type==PassengerType.Food?1:0);if(s.jobs.trip.State==TripState.ToPickup)s.jobs.AdvanceBehavior(Mathf.Max(.01f,s.jobs.Behavior.PreparationRemaining));Check(s.jobs.trip.State==TripState.OnTrip,"authored preparation completes "+definition.id);
    var schedule=s.requests.CaptureLive().schedule;foreach(var slot in schedule.slots)Check(slot.kind!=RequestKind.ShortRoad&&slot.kind!=RequestKind.RouteAdvice,"new default never schedules removed routes");var representative=PassengerRequestUI.Representative(s.jobs.Behavior.RepresentativeType,s.jobs.Behavior.RepresentativeVariant);if(representative.HasValue)Check(schedule.slots.Length>0&&schedule.slots[0].kind==representative.Value,"actual representative request bound "+definition.id);
    RoundTrip();Check(s.jobs.Behavior.PresetId==definition.id&&s.jobs.Behavior.PresetOverrides.Length==definition.overrides.Length,"new default retains authored overrides on JSON restore "+definition.id);Deliver();delivered++;
   }Check(delivered==12,"all twelve new packaged passengers complete real lifecycle");
  }finally{ContentTuning.UseJson(prior);}
 }
 void MainChecks(){
  Fresh();Begin(PassengerType.Luggage);Answer(0);s.jobs.AdvanceBehavior(9);int ordinal=s.business.ledger.Care.Snapshot().encounterOrdinal;s.business.ledger.RequestClose();s.jobs.AdvanceBehavior(1);Check(s.jobs.trip.State==TripState.ToPickup&&!s.jobs.Behavior.Boarded&&s.business.ledger.Care.Snapshot().encounterOrdinal==ordinal,"closing during last load second cannot board or consume encounter");
  Fresh();Begin(PassengerType.General);Stop(0);bool any=false;for(int i=1;i<Mathf.Min(12,s.jobs.stops.Length);i++){s.jobs.nav.SetDestination(s.jobs.stops[0]);int goal=s.jobs.nav.hdGoal;bool destination=s.jobs.nav.HasLargeRoadAlternativeTo(s.jobs.stops[i]);Check(s.jobs.nav.hdGoal==goal,"candidate query preserves pickup destination");s.jobs.nav.SetDestination(s.jobs.stops[i]);bool actual=s.jobs.nav.HasLargeRoadAlternative();Check(destination==actual,"candidate broad-road eligibility matches actual trip destination");any|=destination;}Check(any,"actual map offers a broad-road destination");

  Fresh();Begin(PassengerType.Luggage);Check(s.jobs.trip.State==TripState.ToPickup,"luggage preparation precedes actual boarding");float pickup=s.jobs.trip.PickupRemaining;Answer(0);Check(s.jobs.BehaviorWorkProtected,"required safe work protects deadline");s.jobs.AdvanceBehavior(4);Check(s.jobs.Behavior.PreparationRemaining==6&&s.jobs.trip.PickupRemaining==pickup,"partial load and pickup time protected");RoundTrip();s.paused=true;s.jobs.AdvanceBehavior(99);Check(s.jobs.Behavior.PreparationRemaining==6,"paused load does not advance");s.paused=false;s.jobs.AdvanceBehavior(6);Check(s.jobs.trip.State==TripState.OnTrip,"load completes actual board once");Stop(s.jobs.current.drop);Check(s.jobs.Interact()&&s.jobs.trip.ArrivalLocked&&s.jobs.Active,"arrival locks before unload");int pay=s.jobs.RequestReward.Total;RoundTrip();s.jobs.trip.Tick(999);s.jobs.AdvanceBehavior(10);Check(!s.jobs.Active&&s.business.passengers[0].paid==pay,"unload cannot change first arrival fare");
  foreach(int choice in new[]{0,1,2}){Fresh();Begin(PassengerType.MuddyLuggage);Answer(choice);if(choice==0)s.jobs.AdvanceBehavior(10);else s.jobs.Interact();Check(s.jobs.trip.State==TripState.OnTrip,"mud option boards");Deliver();Check(s.jobs.Cleanliness==(choice==1?93:98),"mud dirt only unprotected exit plus normal exit");}
  foreach(int choice in new[]{-1,0,1,2}){Fresh();Begin(PassengerType.Food);if(choice>=0)Answer(choice);Check(s.jobs.ScoreView.request==(choice==1?5:0),"food choice actual live satisfaction "+choice);if(choice==2){s.jobs.AdvanceBehavior(5);RoundTrip();s.jobs.AdvanceBehavior(5);}s.jobs.Behavior.Advance(25,false,true,.6f,100);s.jobs.ApplyBehaviorDirt();int expected=choice==1?(s.jobs.Behavior.SpillPlanned?92:98):100;Check(s.jobs.Cleanliness==expected,"food actual consumption choice "+choice);RoundTrip();s.jobs.ApplyBehaviorDirt();Check(s.jobs.Cleanliness==expected,"food reload replay safe "+choice);Check(s.jobs.ScoreView.request==(choice==1?5:0),"food restored satisfaction once "+choice);Deliver();Check(s.jobs.RequestReward.satisfactionDelta==(choice==1?5:0),"food actual fare settlement includes consent "+choice);Check(s.jobs.Cleanliness==expected-2,"ordinary exit remains separate "+choice);}
  Fresh();Begin(PassengerType.Food);Answer(1);s.jobs.Behavior.Advance(25,false,true,.6f,100);s.jobs.ApplyBehaviorDirt();string priorEffect=s.jobs.Behavior.DirtEvents[0].Id;Deliver();s.business.ledger.Care.Wash();s.jobs.PrepareForNextCall();Begin(PassengerType.Food);Answer(1);s.jobs.Behavior.Advance(25,false,true,.6f,100);s.jobs.ApplyBehaviorDirt();Check(s.jobs.Behavior.DirtEvents[0].Id!=priorEffect&&s.jobs.Behavior.EffectTripIdentity==s.law.tripId&&s.jobs.Cleanliness==(s.jobs.Behavior.SpillPlanned?92:98),"same candidate on a second actual trip soils after wash");
  Fresh();Begin(PassengerType.Sleeping);s.jobs.Behavior.Advance(40,false,true,.4f,100);Check(s.jobs.BehaviorAsleep,"actual non-drunk sleep");Stop(s.jobs.current.drop);Check(s.jobs.Interact()&&s.jobs.trip.ArrivalLocked&&s.jobs.DrunkRide.Waiting&&!s.jobs.DrunkRide.IsDrunk,"non-drunk first arrival wakes through common policy");pay=s.jobs.RequestReward.Total;RoundTrip();s.jobs.DrunkRide.Advance(30,1);s.jobs.trip.Tick(500);Check(s.jobs.Interact()&&!s.jobs.Active&&s.business.passengers[0].paid==pay,"sleep wait does not change fare");
  foreach(PassengerType type in Enum.GetValues(typeof(PassengerType))){if(type==PassengerType.Luggage||type==PassengerType.MuddyLuggage||type==PassengerType.Food||type==PassengerType.Sleeping)continue;Fresh();Begin(type);RoundTrip();Deliver();}
 }
 void SaveReloadCase(){Fresh();Begin(PassengerType.Food);Answer(1);s.jobs.Behavior.Advance(25,false,true,.6f,100);s.jobs.ApplyBehaviorDirt();s.business.SaveCheckpoint();Check(File.Exists(s.business.SavePath)&&s.business.SavePath.Contains("artifacts"),"isolated on-disk checkpoint");}
 string RestoreDiagnostic(){var loaded=(CampaignCheckpoint)typeof(BusinessProgress).GetField("loaded",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).GetValue(s.business);return "path="+s.business.SavePath+" exists="+File.Exists(s.business.SavePath)+" loaded="+(loaded!=null)+" live="+(loaded!=null&&loaded.live!=null)+" restoring="+typeof(BusinessProgress).GetField("restoring",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).GetValue(s.business)+" state="+s.jobs.trip.State+" type="+(s.jobs.Behavior==null?"null":s.jobs.Behavior.Type.ToString())+" status="+s.business.saveStatus;}
 void ReloadChecks(){report.AppendLine("RESTORE "+RestoreDiagnostic());s.paused=false;s.business.preparing=false;Time.timeScale=1;Check(s.jobs.trip.State==TripState.OnTrip&&s.jobs.Behavior!=null&&s.jobs.Behavior.Type==PassengerType.Food&&s.jobs.Behavior.ConsumptionOccurred,"new process resumes consumed food passenger");Check(s.jobs.ScoreView.request==5,"new process permission reward once");int clean=s.jobs.Cleanliness;s.jobs.ApplyBehaviorDirt();Check(s.jobs.Cleanliness==clean,"new process dirt exactly once");Deliver();Check(s.jobs.Cleanliness==clean-2,"new process normal exit once");Check(s.jobs.RequestReward.satisfactionDelta==5,"new process final fare keeps permission reward");s.business.SaveCheckpoint();}
 IEnumerator Capture(string name){yield return null;yield return new WaitForEndOfFrame();ScreenCapture.CaptureScreenshot(Path.GetFullPath("artifacts/passenger-behavior-"+name+".png"));yield return new WaitForSecondsRealtime(.5f);}
 bool Guard(Action action){try{action();return true;}catch(Exception e){report.AppendLine(e.ToString());Debug.LogException(e);return false;}}
 IEnumerator Start(){
  yield return new WaitForSecondsRealtime(2);s=FindObjectOfType<DriveSession>();while(s&&!s.StartupReady)yield return null;if(s)report.AppendLine("PRE_BOUNDARY "+RestoreDiagnostic());yield return null;yield return null;yield return null;
  // Business.Start restores its live snapshot in a separate next-frame coroutine. Never disable it before that boundary.
  var restoringField=typeof(BusinessProgress).GetField("restoring",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic);float restoreDeadline=Time.realtimeSinceStartup+10;while(s&&(bool)restoringField.GetValue(s.business)&&Time.realtimeSinceStartup<restoreDeadline)yield return null;
  reload=Array.IndexOf(Environment.GetCommandLineArgs(),"-passengerBehaviorReloadTest")>=0;
  if(Array.IndexOf(Environment.GetCommandLineArgs(),"-passengerRosterTest")>=0){bool rosterOk=Guard(()=>{Check(s!=null,"session initialized");FreezeSystems();RosterChecks();});Directory.CreateDirectory("artifacts/passenger-roster-v1");File.WriteAllText("artifacts/passenger-roster-v1/player.txt",(rosterOk?"PASS":"FAIL")+" checks="+checks+"\n"+report);Debug.Log("PASSENGER_ROSTER_PLAYER_"+(rosterOk?"OK":"FAILED")+" checks="+checks);Application.Quit(rosterOk?0:1);yield break;}
  if(Array.IndexOf(Environment.GetCommandLineArgs(),"-passengerOverridesTest")>=0){bool individualOk=Guard(()=>{Check(s!=null,"session initialized");FreezeSystems();OverrideChecks();});Directory.CreateDirectory("artifacts/passenger-overrides");File.WriteAllText("artifacts/passenger-overrides/player.txt",(individualOk?"PASS":"FAIL")+" checks="+checks+"\n"+report);Debug.Log("PASSENGER_OVERRIDES_PLAYER_"+(individualOk?"OK":"FAILED")+" checks="+checks);Application.Quit(individualOk?0:1);yield break;}
  if(Array.IndexOf(Environment.GetCommandLineArgs(),"-passengerCompositionTest")>=0){bool compositionOk=Guard(()=>{Check(s!=null,"session initialized");FreezeSystems();CompositionChecks();});Directory.CreateDirectory("artifacts/passenger-composition");File.WriteAllText("artifacts/passenger-composition/player.txt",(compositionOk?"PASS":"FAIL")+" checks="+checks+"\n"+report);Debug.Log("PASSENGER_COMPOSITION_PLAYER_"+(compositionOk?"OK":"FAILED")+" checks="+checks);Application.Quit(compositionOk?0:1);yield break;}
  bool ok=Guard(()=>{Check(s!=null,"session initialized");Check(!(bool)restoringField.GetValue(s.business),"startup restore completed within10seconds");FreezeSystems();if(reload)ReloadChecks();else MainChecks();});
  if(ok&&!reload){
   ok=Guard(()=>{Fresh();Begin(PassengerType.Food);s.requests.BeginKind(RequestKind.LocalChat);typeof(PassengerRequestUI).GetField("legacy",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).SetValue(s.requests,false);});
   yield return null;
   if(ok)ok=Guard(()=>{s.requests.AdvanceSafeStop(2.1f);Check(s.requests.Choose(PassengerReply.Alternative),"real frame prior I response");Check(!s.jobs.RespondBehavior(1)&&s.jobs.Behavior.Choice==-1,"real frame I does not authorize food");});
   yield return null;
   if(ok)ok=Guard(()=>Check(s.jobs.RespondBehavior(0),"actual next frame permits deliberate food choice"));
  }
  if(ok&&!reload&&Array.IndexOf(Environment.GetCommandLineArgs(),"-passengerBehaviorCapture")>=0){
   ok=Guard(()=>{Fresh();Begin(PassengerType.Luggage);});if(ok)yield return Capture("preparation");
   if(ok)ok=Guard(()=>{Answer(0);s.jobs.AdvanceBehavior(10);Deliver();s.GetComponent<RideCompletionPanel>().ShowLast();});if(ok)yield return Capture("receipt");
   if(ok)ok=Guard(()=>{Fresh();Begin(PassengerType.Food);});if(ok)yield return Capture("food-choice");
   if(ok)ok=Guard(()=>{Answer(1);s.GetComponent<PassengerBehaviorUI>().NotifyStateChanged();});if(ok)yield return Capture("food-allowed");
   if(ok)ok=Guard(()=>{s.jobs.Behavior.SpillPlanned=true;s.jobs.Behavior.Advance(25,false,true,.6f,100);s.jobs.ApplyBehaviorDirt();s.GetComponent<PassengerBehaviorUI>().NotifyStateChanged();});if(ok)yield return Capture("food-spill");
   if(ok)ok=Guard(()=>{Fresh();Begin(PassengerType.General);s.requests.BeginKind(RequestKind.Comfort);s.requests.enabled=true;});if(ok)yield return Capture("request-effects");s.requests.enabled=false;
   if(ok)ok=Guard(()=>{Fresh();Begin(PassengerType.Sleeping);s.jobs.Behavior.Advance(40,false,true,.4f,100);s.requests.SuspendUnansweredForSleep();s.GetComponent<PassengerBehaviorUI>().NotifyStateChanged();});if(ok)yield return Capture("sleeping");
  }
  if(ok&&!reload)ok=Guard(SaveReloadCase);
  Directory.CreateDirectory("artifacts");File.WriteAllText("artifacts/passenger-behavior-"+(reload?"reload":"player")+".txt",(ok?"PASS":"FAIL")+" checks="+checks+"\n"+report);Debug.Log("PASSENGER_BEHAVIOR_PLAYER_"+(ok?"OK":"FAILED")+" checks="+checks);Application.Quit(ok?0:1);
 }
}
